    {"chapter_id":"unit1","difficulty":"easy","question_en":"A computer is best defined as an electronic device that:","question_hi":"कंप्यूटर की सबसे अच्छी परिभाषा है एक इलेक्ट्रॉनिक उपकरण जो:","options_en":["Only prints documents","Accepts data, processes it and gives output","Only plays videos","Replaces human brain completely"],"options_hi":["केवल दस्तावेज़ छापता है","डेटा लेता है, संसाधित करता है और आउटपुट देता है","केवल वीडियो चलाता है","मानव मस्तिष्क को पूरी तरह बदल देता है"],"answer_index":1,"explanation_en":"A computer takes input, processes according to instructions and produces output.","explanation_hi":"कंप्यूटर इनपुट लेता है, निर्देशों के अनुसार प्रसंस्करण करता है और आउटपुट देता है।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"Which is NOT a characteristic of a computer?","question_hi":"इनमें से कौन कंप्यूटर की विशेषता नहीं है?","options_en":["Speed","Accuracy","Emotion","Diligence"],"options_hi":["गति","सटीकता","भावना","परिश्रम"],"answer_index":2,"explanation_en":"Computers do not have emotions; speed, accuracy and diligence are core traits.","explanation_hi":"कंप्यूटर में भावनाएँ नहीं होतीं; गति, सटीकता और परिश्रम इसकी मूल विशेषताएँ हैं।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"The brain of the computer is:","question_hi":"कंप्यूटर का मस्तिष्क है:","options_en":["RAM","Hard disk","CPU","Monitor"],"options_hi":["RAM","हार्ड डिस्क","CPU","मॉनिटर"],"answer_index":2,"explanation_en":"CPU performs all processing and controls the system.","explanation_hi":"CPU सभी प्रसंस्करण करता है और सिस्टम को नियंत्रित करता है।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"CPU stands for:","question_hi":"CPU का पूर्ण रूप है:","options_en":["Central Program Unit","Central Processing Unit","Computer Processing Unit","Control Program Unit"],"options_hi":["Central Program Unit","Central Processing Unit","Computer Processing Unit","Control Program Unit"],"answer_index":1,"explanation_en":"CPU = Central Processing Unit.","explanation_hi":"CPU = Central Processing Unit।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"ALU performs:","question_hi":"ALU कार्य करता है:","options_en":["Only storage","Arithmetic and logical operations","Printing","Only input"],"options_hi":["केवल भंडारण","अंकगणितीय और तार्किक संचालन","मुद्रण","केवल इनपुट"],"answer_index":1,"explanation_en":"ALU = Arithmetic Logic Unit; it does math (+,-) and logic (AND, OR).","explanation_hi":"ALU = अंकगणितीय-तर्क इकाई; यह गणित और तर्क के कार्य करती है।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"CU in CPU stands for:","question_hi":"CPU में CU का अर्थ है:","options_en":["Control Unit","Copy Unit","Count Unit","Core Unit"],"options_hi":["नियंत्रण इकाई","कॉपी इकाई","गणना इकाई","कोर इकाई"],"answer_index":0,"explanation_en":"CU directs operations by fetching and decoding instructions.","explanation_hi":"CU निर्देशों को लाकर और डिकोड करके कार्यों का निर्देशन करती है।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"Hardware refers to:","question_hi":"हार्डवेयर का अर्थ है:","options_en":["Programs","Physical parts you can touch","Internet data","Only RAM"],"options_hi":["प्रोग्राम","भौतिक भाग जिन्हें छू सकें","इंटरनेट डेटा","केवल RAM"],"answer_index":1,"explanation_en":"Hardware is the tangible physical parts of a computer.","explanation_hi":"हार्डवेयर कंप्यूटर के भौतिक भाग होते हैं जिन्हें छुआ जा सकता है।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"Software is:","question_hi":"सॉफ्टवेयर है:","options_en":["Physical parts","Set of instructions","Monitor","Cable"],"options_hi":["भौतिक भाग","निर्देशों का समूह","मॉनिटर","केबल"],"answer_index":1,"explanation_en":"Software is a set of instructions that tells hardware what to do.","explanation_hi":"सॉफ्टवेयर निर्देशों का समूह है जो हार्डवेयर को निर्देश देता है।"},
    {"chapter_id":"unit1","difficulty":"medium","question_en":"Which is an input device?","question_hi":"इनमें से इनपुट उपकरण कौन सा है?","options_en":["Monitor","Printer","Keyboard","Speaker"],"options_hi":["मॉनिटर","प्रिंटर","कीबोर्ड","स्पीकर"],"answer_index":2,"explanation_en":"Keyboard supplies input to the computer.","explanation_hi":"कीबोर्ड कंप्यूटर को इनपुट देता है।"},
