    {"chapter_id":"unit1","difficulty":"easy","question_en":"1 MB equals:","question_hi":"1 MB बराबर है:","options_en":["1000 KB","1024 KB","1024 bytes","100 KB"],"options_hi":["1000 KB","1024 KB","1024 बाइट","100 KB"],"answer_index":1,"explanation_en":"1 MB = 1024 KB.","explanation_hi":"1 MB = 1024 KB।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"1 GB equals:","question_hi":"1 GB बराबर है:","options_en":["1024 KB","1024 MB","1000 MB","1024 bytes"],"options_hi":["1024 KB","1024 MB","1000 MB","1024 बाइट"],"answer_index":1,"explanation_en":"1 GB = 1024 MB.","explanation_hi":"1 GB = 1024 MB।"},
    {"chapter_id":"unit1","difficulty":"medium","question_en":"The 'block diagram' of a computer does NOT include:","question_hi":"कंप्यूटर के ब्लॉक आरेख में शामिल नहीं है:","options_en":["Input unit","Output unit","Browser","Memory unit"],"options_hi":["इनपुट इकाई","आउटपुट इकाई","ब्राउज़र","मेमोरी इकाई"],"answer_index":2,"explanation_en":"A browser is software, not a block in the hardware diagram.","explanation_hi":"ब्राउज़र सॉफ्टवेयर है, हार्डवेयर ब्लॉक आरेख का भाग नहीं।"},
    {"chapter_id":"unit1","difficulty":"easy","question_en":"Scanner is a(n):","question_hi":"स्कैनर है:","options_en":["Output device","Input device","Storage","Processor"],"options_hi":["आउटपुट उपकरण","इनपुट उपकरण","भंडारण","प्रोसेसर"],"answer_index":1,"explanation_en":"Scanner digitises printed images as input.","explanation_hi":"स्कैनर मुद्रित चित्रों को डिजिटल इनपुट में बदलता है।"},
    {"chapter_id":"unit1","difficulty":"medium","question_en":"ULSI technology is used in:","question_hi":"ULSI तकनीक उपयोग होती है:","options_en":["1st-gen","2nd-gen","3rd-gen","5th-gen computers"],"options_hi":["पहली पीढ़ी","दूसरी पीढ़ी","तीसरी पीढ़ी","पाँचवीं पीढ़ी के कंप्यूटर"],"answer_index":3,"explanation_en":"ULSI (Ultra Large Scale Integration) is used in 5th-gen.","explanation_hi":"ULSI पाँचवीं पीढ़ी में उपयोग होती है।"},
    {"chapter_id":"unit1","difficulty":"hard","question_en":"Decimal 255 in hex is:","question_hi":"दशमलव 255 हेक्स में है:","options_en":["FF","F0","FE","AA"],"options_hi":["FF","F0","FE","AA"],"answer_index":0,"explanation_en":"255 = 15×16 + 15 = FF.","explanation_hi":"255 = 15×16 + 15 = FF।"},
    {"chapter_id":"unit1","difficulty":"medium","question_en":"Which is NOT a component inside the system unit?","question_hi":"इनमें से सिस्टम यूनिट के अंदर कौन सा घटक नहीं है?","options_en":["Motherboard","CPU","Monitor","RAM"],"options_hi":["मदरबोर्ड","CPU","मॉनिटर","RAM"],"answer_index":2,"explanation_en":"Monitor is external; motherboard, CPU, RAM are inside.","explanation_hi":"मॉनिटर बाहरी है; मदरबोर्ड, CPU, RAM अंदर होते हैं।"},

    # ========================== UNIT 2 ==========================
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is primary memory?","question_hi":"प्राथमिक मेमोरी कौन सी है?","options_en":["Hard disk","RAM","DVD","Pen drive"],"options_hi":["हार्ड डिस्क","RAM","DVD","पेन ड्राइव"],"answer_index":1,"explanation_en":"RAM is primary (main) memory.","explanation_hi":"RAM प्राथमिक (मुख्य) मेमोरी है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"RAM is:","question_hi":"RAM है:","options_en":["Non-volatile","Volatile","Permanent","Optical"],"options_hi":["नॉन-वोलेटाइल","वोलेटाइल","स्थायी","ऑप्टिकल"],"answer_index":1,"explanation_en":"RAM loses data when power is off (volatile).","explanation_hi":"पावर बंद होने पर RAM का डेटा मिट जाता है (वोलेटाइल)।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"ROM is:","question_hi":"ROM है:","options_en":["Volatile","Non-volatile","Temporary","Cache"],"options_hi":["वोलेटाइल","नॉन-वोलेटाइल","अस्थायी","कैश"],"answer_index":1,"explanation_en":"ROM retains data without power.","explanation_hi":"ROM बिना पावर के भी डेटा बनाए रखती है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Which is secondary storage?","question_hi":"द्वितीयक संग्रहण कौन-सा है?","options_en":["RAM","Cache","Hard Disk","Registers"],"options_hi":["RAM","कैश","हार्ड डिस्क","रजिस्टर"],"answer_index":2,"explanation_en":"Hard disks (and SSD, DVD, pen drive) are secondary storage.","explanation_hi":"हार्ड डिस्क (SSD, DVD, पेन ड्राइव) द्वितीयक संग्रहण हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"SSD stands for:","question_hi":"SSD का पूर्ण रूप है:","options_en":["Solid State Drive","Super Storage Disk","Static System Drive","Serial Storage Disc"],"options_hi":["Solid State Drive","Super Storage Disk","Static System Drive","Serial Storage Disc"],"answer_index":0,"explanation_en":"SSD = Solid State Drive (uses flash memory).","explanation_hi":"SSD = Solid State Drive (फ़्लैश मेमोरी)।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is faster?","question_hi":"कौन अधिक तेज़ है?","options_en":["Hard Disk","SSD","DVD","Magnetic tape"],"options_hi":["हार्ड डिस्क","SSD","DVD","मैग्नेटिक टेप"],"answer_index":1,"explanation_en":"SSDs are much faster than HDDs.","explanation_hi":"SSD, HDD से बहुत तेज़ होते हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"CD / DVD are:","question_hi":"CD / DVD हैं:","options_en":["Magnetic","Optical","Flash","Virtual"],"options_hi":["मैग्नेटिक","ऑप्टिकल","फ़्लैश","वर्चुअल"],"answer_index":1,"explanation_en":"CD and DVD are optical storage media.","explanation_hi":"CD व DVD ऑप्टिकल भंडारण माध्यम हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Pen drive uses which technology?","question_hi":"पेन ड्राइव किस तकनीक पर आधारित है?","options_en":["Magnetic","Optical","Flash memory","Vacuum tube"],"options_hi":["मैग्नेटिक","ऑप्टिकल","फ़्लैश मेमोरी","वैक्यूम ट्यूब"],"answer_index":2,"explanation_en":"Pen drives use flash memory.","explanation_hi":"पेन ड्राइव फ़्लैश मेमोरी का उपयोग करती है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"SRAM is used mainly as:","question_hi":"SRAM मुख्यतः उपयोग होती है:","options_en":["Hard disk","Cache","Printer buffer","Pen drive"],"options_hi":["हार्ड डिस्क","कैश","प्रिंटर बफर","पेन ड्राइव"],"answer_index":1,"explanation_en":"SRAM is fast and used in CPU cache.","explanation_hi":"SRAM तेज़ है और CPU कैश में उपयोग होती है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"DRAM needs:","question_hi":"DRAM को आवश्यकता है:","options_en":["No refresh","Periodic refresh","Only ROM","Only cache"],"options_hi":["रिफ़्रेश की नहीं","आवधिक रिफ़्रेश","केवल ROM","केवल कैश"],"answer_index":1,"explanation_en":"DRAM must be periodically refreshed to retain data.","explanation_hi":"DRAM का डेटा बनाए रखने के लिए आवधिक रिफ़्रेश ज़रूरी है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Which is a type of ROM?","question_hi":"इनमें से ROM का प्रकार कौन सा है?","options_en":["SRAM","DRAM","EEPROM","SSD"],"options_hi":["SRAM","DRAM","EEPROM","SSD"],"answer_index":2,"explanation_en":"EEPROM = Electrically Erasable Programmable ROM.","explanation_hi":"EEPROM = Electrically Erasable Programmable ROM।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Operating System is:","question_hi":"ऑपरेटिंग सिस्टम है:","options_en":["Application software","System software","Hardware","Browser"],"options_hi":["एप्लिकेशन सॉफ्टवेयर","सिस्टम सॉफ्टवेयर","हार्डवेयर","ब्राउज़र"],"answer_index":1,"explanation_en":"OS is system software that manages hardware.","explanation_hi":"OS सिस्टम सॉफ्टवेयर है जो हार्डवेयर को प्रबंधित करता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is NOT an operating system?","question_hi":"कौन-सा ऑपरेटिंग सिस्टम नहीं है?","options_en":["Windows","Linux","Android","MS Word"],"options_hi":["Windows","Linux","Android","MS Word"],"answer_index":3,"explanation_en":"MS Word is an application; the rest are OSes.","explanation_hi":"MS Word एप्लिकेशन है; बाकी OS हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is application software?","question_hi":"कौन-सा एप्लिकेशन सॉफ्टवेयर है?","options_en":["Linux kernel","MS Excel","Device driver","BIOS"],"options_hi":["Linux कर्नेल","MS Excel","डिवाइस ड्राइवर","BIOS"],"answer_index":1,"explanation_en":"Excel is an application program for end users.","explanation_hi":"Excel अंतिम उपयोगकर्ता के लिए एप्लिकेशन है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"The main job of an OS is NOT:","question_hi":"OS का मुख्य कार्य नहीं है:","options_en":["Process management","Memory management","File management","Playing games"],"options_hi":["प्रोसेस प्रबंधन","मेमोरी प्रबंधन","फ़ाइल प्रबंधन","गेम खेलना"],"answer_index":3,"explanation_en":"Games are applications; OS manages resources.","explanation_hi":"गेम एप्लिकेशन हैं; OS संसाधन प्रबंधित करता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"MS Word is used for:","question_hi":"MS Word उपयोग होता है:","options_en":["Spreadsheets","Presentations","Word processing","Browsing"],"options_hi":["स्प्रेडशीट","प्रस्तुति","शब्द संसाधन","ब्राउज़िंग"],"answer_index":2,"explanation_en":"MS Word is a word processor.","explanation_hi":"MS Word शब्द संसाधक है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Default extension of a Word document is:","question_hi":"Word दस्तावेज़ का डिफ़ॉल्ट एक्सटेंशन है:","options_en":[".xlsx",".pptx",".docx",".txt"],"options_hi":[".xlsx",".pptx",".docx",".txt"],"answer_index":2,"explanation_en":"Modern Word files use .docx.","explanation_hi":"आधुनिक Word फ़ाइलें .docx होती हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Default extension of an Excel file is:","question_hi":"Excel फ़ाइल का डिफ़ॉल्ट एक्सटेंशन है:","options_en":[".docx",".xlsx",".pptx",".pdf"],"options_hi":[".docx",".xlsx",".pptx",".pdf"],"answer_index":1,"explanation_en":"Excel files use .xlsx.","explanation_hi":"Excel की फ़ाइलें .xlsx होती हैं।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Default extension of a PowerPoint file is:","question_hi":"PowerPoint फ़ाइल का डिफ़ॉल्ट एक्सटेंशन है:","options_en":[".docx",".xlsx",".pptx",".txt"],"options_hi":[".docx",".xlsx",".pptx",".txt"],"answer_index":2,"explanation_en":"PowerPoint saves as .pptx.","explanation_hi":"PowerPoint .pptx में सहेजता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"In Excel, a cell is identified by:","question_hi":"Excel में सेल की पहचान होती है:","options_en":["Only row","Only column","Column letter + row number","By colour"],"options_hi":["केवल पंक्ति","केवल स्तंभ","स्तंभ अक्षर + पंक्ति संख्या","रंग से"],"answer_index":2,"explanation_en":"Cells like A1, B2 use column letter + row number.","explanation_hi":"A1, B2 जैसे सेल स्तंभ+पंक्ति से पहचाने जाते हैं।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Which Excel formula gives the sum of A1 to A5?","question_hi":"कौन-सा Excel सूत्र A1 से A5 तक का योग देता है?","options_en":["=TOTAL(A1:A5)","=SUM(A1:A5)","=ADD(A1:A5)","=PLUS(A1:A5)"],"options_hi":["=TOTAL(A1:A5)","=SUM(A1:A5)","=ADD(A1:A5)","=PLUS(A1:A5)"],"answer_index":1,"explanation_en":"=SUM(range) totals the given range.","explanation_hi":"=SUM(रेंज) दिए गए रेंज का योग देता है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Which Excel function returns the mean?","question_hi":"कौन-सा Excel फ़ंक्शन औसत देता है?","options_en":["=MEAN","=MEDIAN","=AVERAGE","=AVG"],"options_hi":["=MEAN","=MEDIAN","=AVERAGE","=AVG"],"answer_index":2,"explanation_en":"=AVERAGE(range) returns the arithmetic mean.","explanation_hi":"=AVERAGE(रेंज) अंकगणितीय औसत देता है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"=IF(A1>10,\"Yes\",\"No\") is a:","question_hi":"=IF(A1>10,\"Yes\",\"No\") है:","options_en":["Statistical function","Logical function","Date function","Lookup function"],"options_hi":["सांख्यिकीय","तार्किक","दिनांक","लुकअप"],"answer_index":1,"explanation_en":"IF is a logical function.","explanation_hi":"IF एक तार्किक फ़ंक्शन है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"A workbook contains:","question_hi":"वर्कबुक में होती है(हैं):","options_en":["One cell","Only rows","One or more worksheets","Only charts"],"options_hi":["एक सेल","केवल पंक्तियाँ","एक या अधिक वर्कशीट","केवल चार्ट"],"answer_index":2,"explanation_en":"A workbook contains sheets which contain cells.","explanation_hi":"वर्कबुक में शीट होती हैं जिनमें सेल होते हैं।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Which chart is best for part-of-whole data?","question_hi":"किसी पूरे का भाग दिखाने के लिए कौन सा चार्ट उपयुक्त है?","options_en":["Line","Bar","Pie","Scatter"],"options_hi":["लाइन","बार","पाई","स्कैटर"],"answer_index":2,"explanation_en":"Pie chart shows proportions of a whole.","explanation_hi":"पाई चार्ट किसी पूरे के अनुपात दिखाता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Slide show in PowerPoint starts with key:","question_hi":"PowerPoint में स्लाइड शो शुरू करने की कुंजी है:","options_en":["F2","F5","F8","F12"],"options_hi":["F2","F5","F8","F12"],"answer_index":1,"explanation_en":"F5 starts the slide show from first slide.","explanation_hi":"F5 पहली स्लाइड से शो शुरू करता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Transitions are applied to:","question_hi":"ट्रांज़िशन लगाए जाते हैं:","options_en":["Letters","Slides","Formulas","Cells"],"options_hi":["अक्षरों पर","स्लाइडों पर","सूत्रों पर","सेल पर"],"answer_index":1,"explanation_en":"Transitions move from one slide to the next.","explanation_hi":"ट्रांज़िशन एक स्लाइड से अगली स्लाइड पर जाने के लिए।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Mail Merge is a feature of:","question_hi":"मेल मर्ज किसकी सुविधा है?","options_en":["Excel","Word","PowerPoint","Paint"],"options_hi":["Excel","Word","PowerPoint","Paint"],"answer_index":1,"explanation_en":"Mail Merge is used in Word to send personalised letters.","explanation_hi":"मेल मर्ज Word में व्यक्तिगत पत्रों के लिए।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Keyboard shortcut to save in Office apps is:","question_hi":"ऑफिस ऐप्स में सहेजने का शॉर्टकट है:","options_en":["Ctrl+P","Ctrl+S","Ctrl+C","Ctrl+V"],"options_hi":["Ctrl+P","Ctrl+S","Ctrl+C","Ctrl+V"],"answer_index":1,"explanation_en":"Ctrl+S saves the current file.","explanation_hi":"Ctrl+S वर्तमान फ़ाइल सहेजता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Ctrl+C is used for:","question_hi":"Ctrl+C का उपयोग है:","options_en":["Cut","Copy","Paste","Print"],"options_hi":["काटना","कॉपी","पेस्ट","प्रिंट"],"answer_index":1,"explanation_en":"Ctrl+C copies the selection.","explanation_hi":"Ctrl+C चयन को कॉपी करता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Ctrl+V is used for:","question_hi":"Ctrl+V का उपयोग है:","options_en":["Save","Paste","View","Cut"],"options_hi":["सहेजना","पेस्ट","दिखाना","काटना"],"answer_index":1,"explanation_en":"Ctrl+V pastes the clipboard content.","explanation_hi":"Ctrl+V क्लिपबोर्ड की सामग्री पेस्ट करता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is a web browser?","question_hi":"कौन-सा वेब ब्राउज़र है?","options_en":["Google Chrome","MS Word","Excel","Windows"],"options_hi":["Google Chrome","MS Word","Excel","Windows"],"answer_index":0,"explanation_en":"Chrome is a browser.","explanation_hi":"Chrome एक ब्राउज़र है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"The device driver is:","question_hi":"डिवाइस ड्राइवर है:","options_en":["Hardware part","Browser","System software","Game"],"options_hi":["हार्डवेयर","ब्राउज़र","सिस्टम सॉफ्टवेयर","गेम"],"answer_index":2,"explanation_en":"Drivers are system software that let OS talk to devices.","explanation_hi":"ड्राइवर सिस्टम सॉफ्टवेयर है जो OS को उपकरणों से बात कराता है।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"BIOS is stored in:","question_hi":"BIOS संग्रहित होता है:","options_en":["RAM","Hard Disk","ROM","Cache"],"options_hi":["RAM","हार्ड डिस्क","ROM","कैश"],"answer_index":2,"explanation_en":"BIOS firmware lives in ROM/flash on the motherboard.","explanation_hi":"BIOS मदरबोर्ड की ROM/फ़्लैश में होता है।"},
    {"chapter_id":"unit2","difficulty":"hard","question_en":"Which is the fastest memory below?","question_hi":"नीचे दी गई सबसे तेज़ मेमोरी कौन-सी है?","options_en":["RAM","Register","Cache","Hard disk"],"options_hi":["RAM","रजिस्टर","कैश","हार्ड डिस्क"],"answer_index":1,"explanation_en":"Registers are the fastest, inside the CPU.","explanation_hi":"रजिस्टर सबसे तेज़ हैं, CPU के अंदर।"},
    {"chapter_id":"unit2","difficulty":"medium","question_en":"Compiler converts:","question_hi":"कंपाइलर बदलता है:","options_en":["Machine code to high-level code","High-level code to machine code","HTML to CSS","Image to text"],"options_hi":["मशीन कोड को उच्च-स्तरीय में","उच्च-स्तरीय कोड को मशीन कोड में","HTML को CSS में","चित्र को पाठ में"],"answer_index":1,"explanation_en":"Compilers translate high-level programs into machine code.","explanation_hi":"कंपाइलर उच्च-स्तरीय प्रोग्राम को मशीन कोड में बदलता है।"},
    {"chapter_id":"unit2","difficulty":"easy","question_en":"Which is NOT an output device?","question_hi":"कौन-सा आउटपुट उपकरण नहीं है?","options_en":["Monitor","Printer","Keyboard","Speaker"],"options_hi":["मॉनिटर","प्रिंटर","कीबोर्ड","स्पीकर"],"answer_index":2,"explanation_en":"Keyboard is an input device.","explanation_hi":"कीबोर्ड इनपुट उपकरण है।"},
